#include "../engine/native/smoke/gpu.hpp"
#include "../third_party/json.hpp"
#include "d3d12_test_rig.hpp"
#include <algorithm>
#include <cmath>
#include <limits>
namespace s=engine::smoke;using gpu_test::Rig;
namespace {
unsigned checks=0,groups=0;std::uint64_t comparisons=0;auto cases=nlohmann::json::array();
void require(bool ok,const char* why){++checks;if(!ok)throw std::runtime_error(why);}
template<class F>void throws(F f,const char* why){bool caught=false;try{f();}catch(const std::exception&){caught=true;}require(caught,why);}
float component(engine::Vec3 v,unsigned a){return a==0?v.x:a==1?v.y:v.z;}
unsigned index(const s::Spec& p,unsigned x,unsigned y,unsigned z){return (z*p.dimensions[1]+y)*p.dimensions[0]+x;}
s::Spec quiet(){s::Spec p;p.dimensions={6,6,6};p.maxSpeed=1;p.densityDecay=p.cooling=p.fuelDecay=p.buoyancy=p.smokeWeight=p.vorticity=0;return p;}
void tick(Rig& rig,s::GpuSmokeFireSolver& solver,unsigned at,float dt){rig.begin();std::string error;require(solver.step(rig.commands.p,rig.ticket(),at,dt,error),error.c_str());rig.submit();solver.collect();}
struct Readback {s::State state;std::vector<engine::Vec3> diagnostics;std::vector<float> pressure;};
Readback read(Rig& rig,s::GpuSmokeFireSolver& solver){
    const auto b=solver.buffers();require(b.scalars&&b.velocity&&b.pressure&&b.diagnostics,"Solver outputs unavailable");gpu_test::Com<ID3D12Resource> scalar,velocity,pressure,diagnostics;const auto scalarBytes=std::uint64_t(b.layout.scalarCount)*4,vectorBytes=std::uint64_t(b.layout.cells)*12,pressureBytes=std::uint64_t(b.layout.cells)*4;
    gpu_test::makeBuffer(rig.device.p,scalar,scalarBytes,D3D12_HEAP_TYPE_READBACK,D3D12_RESOURCE_STATE_COPY_DEST);gpu_test::makeBuffer(rig.device.p,velocity,vectorBytes,D3D12_HEAP_TYPE_READBACK,D3D12_RESOURCE_STATE_COPY_DEST);gpu_test::makeBuffer(rig.device.p,pressure,pressureBytes,D3D12_HEAP_TYPE_READBACK,D3D12_RESOURCE_STATE_COPY_DEST);gpu_test::makeBuffer(rig.device.p,diagnostics,vectorBytes,D3D12_HEAP_TYPE_READBACK,D3D12_RESOURCE_STATE_COPY_DEST);
    rig.begin();std::string error;require(solver.prepareRead(rig.commands.p,rig.ticket(),error),error.c_str());const auto copy=[&](ID3D12Resource* source,ID3D12Resource* target,std::uint64_t bytes){gpu_test::transition(rig.commands.p,source,D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE,D3D12_RESOURCE_STATE_COPY_SOURCE);rig.commands.p->CopyBufferRegion(target,0,source,0,bytes);gpu_test::transition(rig.commands.p,source,D3D12_RESOURCE_STATE_COPY_SOURCE,D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);};copy(b.scalars,scalar.p,scalarBytes);copy(b.velocity,velocity.p,vectorBytes);copy(b.pressure,pressure.p,pressureBytes);copy(b.diagnostics,diagnostics.p,vectorBytes);rig.submit();
    Readback out;out.state.scalars.resize(b.layout.scalarCount);out.state.velocity.resize(b.layout.cells);out.pressure.resize(b.layout.cells);out.diagnostics.resize(b.layout.cells);const auto map=[&](ID3D12Resource* source,void* output,std::uint64_t bytes){void* data=nullptr;D3D12_RANGE range{0,bytes},none{0,0};gpu_test::hr(source->Map(0,&range,&data),"Read completed smoke test data");std::memcpy(output,data,bytes);source->Unmap(0,&none);};map(scalar.p,out.state.scalars.data(),scalarBytes);map(velocity.p,out.state.velocity.data(),vectorBytes);map(pressure.p,out.pressure.data(),pressureBytes);map(diagnostics.p,out.diagnostics.data(),vectorBytes);return out;
}
void compare(const s::Spec& p,const s::State& reference,const Readback& gpu,float scalarTolerance=.002f,float velocityTolerance=.0002f){
    require(reference.scalars.size()==gpu.state.scalars.size()&&reference.velocity.size()==gpu.state.velocity.size(),"CPU/GPU smoke layouts differ");float maxScalar=0,maxVelocity=0;for(unsigned i=0;i<reference.scalars.size();++i){maxScalar=std::max(maxScalar,std::abs(reference.scalars[i]-gpu.state.scalars[i]));require(std::isfinite(gpu.state.scalars[i])&&std::abs(reference.scalars[i]-gpu.state.scalars[i])<=scalarTolerance,"GPU scalar differs from CPU visual reference");++comparisons;}for(unsigned i=0;i<reference.velocity.size();++i)for(unsigned a=0;a<3;++a){const auto actual=component(gpu.state.velocity[i],a);maxVelocity=std::max(maxVelocity,std::abs(actual-component(reference.velocity[i],a)));require(std::isfinite(actual)&&std::abs(actual)<=p.maxSpeed+.00001f&&std::abs(actual-component(reference.velocity[i],a))<=velocityTolerance,"GPU face velocity differs from CPU reference/bound");++comparisons;}cases.push_back({{"case","comparison"},{"maxScalarError",maxScalar},{"maxFaceError",maxVelocity}});
}
void close(Rig& rig,s::GpuSmokeFireSolver& solver){solver.collect();std::string error;require(solver.shutdown(error)&&solver.stats().allocationBytes==0,error.c_str());require(rig.fence.p->GetCompletedValue()>=rig.submitted,"Test exited before actual queue completion");}
void equilibrium(Rig& rig){auto p=quiet();auto state=s::initialState(p);const auto l=s::layout(p);std::fill_n(state.scalars.begin()+l.offsets[0],l.cells,1);std::fill_n(state.scalars.begin()+l.offsets[2],l.cells,.5f);std::vector<s::CellInput> in(l.cells);s::GpuSmokeFireSolver solver(rig.device.p,rig.fence.p,p);std::string error;require(solver.setInputs(in,error,&state),error.c_str());s::Diagnostics reference;for(unsigned i=0;i<3;++i){reference=s::step(p,in,state,1.f/120);tick(rig,solver,i,1.f/120);}const auto gpu=read(rig,solver);require(solver.buffers().sourceTick==2&&solver.buffers().version==3&&solver.buffers().spec.cellMetres==p.cellMetres,"Borrowed smoke output omitted its committed source time/version or metre grid");compare(p,state,gpu,.0001f,.00001f);require(std::abs(reference.densityIntegral-double(l.cells)*std::pow(p.cellMetres,3))<1e-8&&reference.divergenceAfterL2==0,"Closed stationary reference changed uniform density or generated flow");for(auto v:gpu.diagnostics)require(v.x==0&&v.y==0&&v.z==0,"Stationary GPU field has nonzero residual");cases.push_back({{"case","equilibrium"},{"ticks",3},{"densityIntegral",reference.densityIntegral}});close(rig,solver);++groups;}
void pressureAndBarrier(Rig& rig){
    auto p=quiet();p.dimensions={8,7,6};p.maxSpeed=4;p.pressureIterations=128;p.vorticity=.15f;auto state=s::initialState(p);const auto l=s::layout(p);std::vector<s::CellInput> in(l.cells);for(unsigned z=0;z<p.dimensions[2];++z)for(unsigned y=0;y<p.dimensions[1];++y)for(unsigned x=0;x<p.dimensions[0];++x){const auto i=index(p,x,y,z);in[i].solid=x==4;state.scalars[l.offsets[0]+i]=x<4?2.f:0.f;state.velocity[i]={.2f*std::sin(i*.17f),.15f*std::cos(i*.11f),.1f*std::sin(i*.23f)};}
    s::GpuSmokeFireSolver solver(rig.device.p,rig.fence.p,p);std::string error;require(solver.setInputs(in,error,&state),error.c_str());const auto reference=s::step(p,in,state,1.f/120);tick(rig,solver,0,1.f/120);auto gpu=read(rig,solver);compare(p,state,gpu);double before=0,after=0;unsigned fluid=0;for(unsigned i=0;i<l.cells;++i)if(!in[i].solid){const auto v=gpu.diagnostics[i];before+=double(v.x)*v.x;after+=double(v.y)*v.y;require(std::abs(v.y-v.z)<.00003f,"GPU pressure residual does not match D(G(p)) correction");++fluid;}before=std::sqrt(before/fluid);after=std::sqrt(after/fluid);require(before>.01&&after<before*.25&&std::abs(after-reference.divergenceAfterL2)<.0001,"MAC pressure solve failed to reduce measured divergence");
    for(unsigned tickIndex=1;tickIndex<5;++tickIndex){s::step(p,in,state,1.f/120);tick(rig,solver,tickIndex,1.f/120);}gpu=read(rig,solver);compare(p,state,gpu,.003f,.0003f);for(unsigned z=0;z<p.dimensions[2];++z)for(unsigned y=0;y<p.dimensions[1];++y)for(unsigned x=4;x<p.dimensions[0];++x)require(gpu.state.scalars[l.offsets[0]+index(p,x,y,z)]==0,"Scalar smoke crossed a one-cell solid barrier");cases.push_back({{"case","pressure-and-solid-barrier"},{"beforeL2",before},{"afterL2",after},{"ratio",after/before},{"ticks",5}});close(rig,solver);++groups;
}
void movingSolid(Rig& rig){auto p=quiet();p.dimensions={7,6,5};p.maxSpeed=4;p.pressureIterations=160;auto state=s::initialState(p);const auto l=s::layout(p);std::vector<s::CellInput> in(l.cells);for(unsigned z=0;z<p.dimensions[2];++z)for(unsigned y=0;y<p.dimensions[1];++y)for(unsigned x=0;x<p.dimensions[0];++x){const auto i=index(p,x,y,z);in[i].solid=x>=2&&x<=3&&y>=2&&y<=3&&z==2;if(in[i].solid)in[i].wallVelocity={.3f,-.1f,.2f};state.scalars[l.offsets[0]+i]=1;}
    s::GpuSmokeFireSolver solver(rig.device.p,rig.fence.p,p);std::string error;require(solver.setInputs(in,error,&state),error.c_str());const auto d=s::step(p,in,state,1.f/120);tick(rig,solver,0,1.f/120);const auto gpu=read(rig,solver);compare(p,state,gpu);unsigned contacts=0;for(unsigned z=0;z<p.dimensions[2];++z)for(unsigned y=0;y<p.dimensions[1];++y)for(unsigned x=0;x<p.dimensions[0];++x){const auto i=index(p,x,y,z);if(in[i].solid)require(gpu.state.scalars[l.offsets[0]+i]==0&&gpu.state.scalars[l.offsets[1]+i]==p.ambientKelvin,"Solid interior retained smoke or heat");const unsigned c[]={x,y,z};for(unsigned a=0;a<3;++a){auto n=std::array<unsigned,3>{x,y,z};n[a]++;if(c[a]+1>=p.dimensions[a]){require(component(gpu.state.velocity[i],a)==0,"Outer boundary leaked normal velocity");continue;}const auto j=index(p,n[0],n[1],n[2]);if(in[i].solid!=in[j].solid){const auto expected=component(in[in[i].solid?i:j].wallVelocity,a);require(std::abs(component(gpu.state.velocity[i],a)-expected)<1e-6f,"Moving obstacle normal velocity was not imposed");++contacts;}}}require(contacts>0&&d.divergenceAfterL2<d.divergenceBeforeL2*.35,"Moving-solid projection did not reduce divergence");cases.push_back({{"case","moving-solid"},{"checkedNormalFaces",contacts},{"beforeL2",d.divergenceBeforeL2},{"afterL2",d.divergenceAfterL2}});close(rig,solver);++groups;}
void combustionAndCooling(Rig& rig){auto p=quiet();p.dimensions={5,5,5};p.burnRate=3;p.sootPerFuel=.4f;auto state=s::initialState(p);const auto l=s::layout(p);std::fill_n(state.scalars.begin(),l.cells,.1f);std::fill_n(state.scalars.begin()+l.offsets[1],l.cells,1000);std::fill_n(state.scalars.begin()+l.offsets[2],l.cells,.5f);std::vector<s::CellInput> in(l.cells);s::GpuSmokeFireSolver solver(rig.device.p,rig.fence.p,p);std::string error;require(solver.setInputs(in,error,&state),error.c_str());s::step(p,in,state,.02f);tick(rig,solver,0,.02f);auto gpu=read(rig,solver);compare(p,state,gpu);const float burned=.5f*(1-std::exp(-p.burnRate*.02f));for(unsigned i=0;i<l.cells;++i)require(std::abs(gpu.state.scalars[l.offsets[2]+i]-(.5f-burned))<1e-6f&&std::abs(gpu.state.scalars[l.offsets[0]+i]-(.1f+p.sootPerFuel*burned))<1e-6f&&std::abs(gpu.state.scalars[l.offsets[1]+i]-(1000+p.heatPerFuel*burned))<.001f,"Uniform combustion differs from the declared exponential burn law");
    for(auto& c:in)c.temperatureRate=-100000;require(solver.setInputs(in,error),error.c_str());const auto remaining=state.scalars[l.offsets[2]];s::step(p,in,state,.02f);tick(rig,solver,1,.02f);gpu=read(rig,solver);compare(p,state,gpu);require(std::abs(gpu.state.scalars[l.offsets[2]]-remaining)<1e-6f&&std::abs(gpu.state.scalars[l.offsets[1]]-p.ambientKelvin)<.0001f,"Cooling below ignition did not extinguish the fuel reaction");cases.push_back({{"case","combustion-extinction"},{"burnedFuel",burned},{"remainingAfterExtinction",remaining}});close(rig,solver);++groups;}
void boundsAndCfl(Rig& rig){auto p=quiet();p.dimensions={4,4,4};p.maxDensity=p.maxFuel=1;p.maxTemperature=1200;p.burnRate=0;auto state=s::initialState(p);const auto l=s::layout(p);std::vector<s::CellInput> in(l.cells);for(auto& c:in){c.densityRate=c.temperatureRate=c.fuelRate=100000;}s::GpuSmokeFireSolver solver(rig.device.p,rig.fence.p,p);std::string error;require(solver.setInputs(in,error,&state),error.c_str());const auto d=s::step(p,in,state,.01f);tick(rig,solver,0,.01f);const auto gpu=read(rig,solver);compare(p,state,gpu);require(d.clampedValues>=3*l.cells&&gpu.state.scalars[0]==1&&gpu.state.scalars[l.offsets[1]]==1200&&gpu.state.scalars[l.offsets[2]]==1,"Declared scalar clamps were not applied");auto before=state;s::Spec capped=p;capped.maxSubsteps=1;throws([&]{s::step(capped,in,state,.25f);},"CPU silently truncated a CFL substep schedule");require(state.scalars==before.scalars,"Rejected CPU schedule mutated state");const auto commands=solver.stats().dispatches;rig.begin();require(!solver.step(rig.commands.p,rig.ticket(),1,std::numeric_limits<float>::quiet_NaN(),error)&&solver.stats().dispatches==commands&&!solver.stats().failed,"Invalid GPU dt recorded partial work or poisoned a usable solver");rig.submit();cases.push_back({{"case","bounds-and-cfl"},{"clampedValues",d.clampedValues},{"invalidScheduleNoMutation",true}});close(rig,solver);++groups;}
void optionalChannelsAndBudget(Rig& rig){auto p=quiet();p.dimensions={32,16,16};p.channels=s::Density;p.macCormack=false;p.pressureIterations=4;const auto l=s::layout(p);auto full=p;full.channels=7;s::GpuSmokeFireSolver solver(rig.device.p,rig.fence.p,p),all(rig.device.p,rig.fence.p,full);require(l.scalarCount==l.cells&&solver.stats().allocationBytes<all.stats().allocationBytes,"Unused scalar channels still allocated full packed storage");std::string error;require(all.shutdown(error),error.c_str());std::vector<s::CellInput> in(l.cells);in[0].temperatureRate=1;const auto bytes=solver.stats().allocationBytes;require(!solver.setInputs(in,error)&&solver.stats().allocationBytes==bytes,"Undeclared source channel was silently ignored or allocated");in[0].temperatureRate=0;auto state=s::initialState(p);require(solver.setInputs(in,error,&state),error.c_str());s::step(p,in,state,1.f/120);tick(rig,solver,0,1.f/120);compare(p,state,read(rig,solver),.000001f,.000001f);throws([&]{s::GpuSmokeFireSolver rejected(rig.device.p,rig.fence.p,p,{1,8,4096});},"Field allocation budget was silently exceeded");s::GpuSmokeFireSolver dispatchLimited(rig.device.p,rig.fence.p,p,{64*1024*1024,8,1});rig.begin();require(!dispatchLimited.step(rig.commands.p,rig.ticket(),0,1.f/120,error)&&dispatchLimited.stats().dispatches==0&&dispatchLimited.stats().inputSnapshots==0,"Dispatch budget recorded initialization before rejection");rig.submit();close(rig,dispatchLimited);cases.push_back({{"case","optional-channels-budget"},{"enabledScalars",l.scalarCount},{"cells",l.cells},{"inactiveChannelRejected",true}});close(rig,solver);++groups;}
void realFenceInputs(Rig& rig){auto p=quiet();p.dimensions={4,4,4};p.channels=s::Density;p.macCormack=false;p.pressureIterations=4;const auto l=s::layout(p);std::vector<s::CellInput> a(l.cells),b(l.cells),c(l.cells);for(unsigned i=0;i<l.cells;++i){a[i].densityRate=1;b[i].densityRate=3;c[i].densityRate=9;}s::GpuSmokeFireSolver solver(rig.device.p,rig.fence.p,p,{16*1024*1024,2,4096});std::string error;require(solver.setInputs(a,error),error.c_str());gpu_test::Com<ID3D12Fence> gate;gpu_test::hr(rig.device.p->CreateFence(0,D3D12_FENCE_FLAG_NONE,IID_PPV_ARGS(gate.out())),"Create smoke input gate");struct Release{ID3D12Fence* fence;~Release(){fence->Signal(1);}} release{gate.p};gpu_test::hr(rig.queue.p->Wait(gate.p,1),"Gate smoke input queue");rig.begin();bool recorded=solver.step(rig.commands.p,rig.ticket(),0,.01f,error);recorded=solver.setInputs(b,error)&&recorded;recorded=solver.step(rig.commands.p,rig.ticket(),1,.01f,error)&&recorded;const auto bytes=solver.stats().allocationBytes;const bool rejected=!solver.setInputs(c,error)&&solver.stats().allocationBytes==bytes;rig.submit(false);const auto blocked=solver.stats();const bool retained=!solver.shutdown(error);gpu_test::hr(gate.p->Signal(1),"Release smoke input queue");rig.wait();require(recorded&&rejected&&retained&&blocked.inputSnapshots==2,"Input snapshot capacity/lifetime was not protected by the actual queue fence");solver.collect();auto gpu=read(rig,solver);for(auto value:gpu.state.scalars)require(std::abs(value-.04f)<1e-6f,"Later source upload overwrote earlier queued inputs");require(solver.stats().inputSnapshots==1&&solver.setInputs(c,error),"Completed input snapshot was not reclaimed");tick(rig,solver,2,.01f);gpu=read(rig,solver);for(auto value:gpu.state.scalars)require(std::abs(value-.13f)<1e-6f,"Source update reset accumulated smoke state");cases.push_back({{"case","actual-fence-inputs"},{"ticksAtOneFence",2},{"snapshotsWhileBlocked",blocked.inputSnapshots},{"laterInputDidNotOverwriteEarlier",true}});close(rig,solver);++groups;}
void nonuniformTransport(Rig& rig){
    auto p=quiet();p.dimensions={9,7,5};p.cellMetres=.2f;p.maxSpeed=4;p.pressureIterations=64;p.vorticity=.2f;p.buoyancy=.003f;p.smokeWeight=.05f;p.cooling=.1f;p.densityDecay=.02f;p.fuelDecay=.01f;p.burnRate=0;auto initial=s::initialState(p);const auto l=s::layout(p);std::vector<s::CellInput> in(l.cells);
    for(unsigned z=0;z<p.dimensions[2];++z)for(unsigned y=0;y<p.dimensions[1];++y)for(unsigned x=0;x<p.dimensions[0];++x){const auto i=index(p,x,y,z);const float rx=float(x)-3,ry=float(y)-2,rz=float(z)-2,b=std::exp(-(rx*rx+ry*ry+rz*rz)*.35f);initial.scalars[l.offsets[0]+i]=2*b;initial.scalars[l.offsets[1]+i]=p.ambientKelvin+500*b;initial.scalars[l.offsets[2]+i]=.2f*b;initial.velocity[i]={-.3f*(float(y)-3),.3f*(float(x)-4),.1f*std::sin(float(x+y))};in[i].solid=x==4&&y==3&&z==2;if(x==2&&y==2&&z==2){in[i].densityRate=.8f;in[i].temperatureRate=20;in[i].fuelRate=.1f;}}
    auto reference=initial,firstOrder=initial;auto linear=p;linear.macCormack=false;s::GpuSmokeFireSolver solver(rig.device.p,rig.fence.p,p);std::string error;require(solver.setInputs(in,error,&initial),error.c_str());for(unsigned i=0;i<2;++i){const auto d=s::step(p,in,reference,.07f);require(d.substeps==3,"Stable multistep schedule was not applied");s::step(linear,in,firstOrder,.07f);tick(rig,solver,i,.07f);}const auto gpu=read(rig,solver);compare(p,reference,gpu,.005f,.0003f);float difference=0;for(unsigned i=0;i<l.cells;++i){difference=std::max(difference,std::abs(reference.scalars[l.offsets[0]+i]-firstOrder.scalars[l.offsets[0]+i]));require(gpu.state.scalars[l.offsets[0]+i]>=0&&gpu.state.scalars[l.offsets[0]+i]<=p.maxDensity&&gpu.state.scalars[l.offsets[1]+i]>=p.ambientKelvin&&gpu.state.scalars[l.offsets[1]+i]<=p.maxTemperature,"Corrected transport escaped scalar bounds");}require(difference>.0001f&&solver.stats().dispatches==452,"MacCormack made no measurable change or a substep/pass was skipped");cases.push_back({{"case","nonuniform-maccormack-substeps"},{"substepsPerTick",3},{"ticks",2},{"dispatches",solver.stats().dispatches},{"differenceFromFirstOrder",difference}});close(rig,solver);++groups;
}
void singleSnapshotReuse(Rig& rig){
    auto p=quiet();p.dimensions={4,4,4};p.channels=s::Density;p.macCormack=false;p.pressureIterations=4;const auto l=s::layout(p);std::vector<s::CellInput> in(l.cells);for(auto& c:in)c.densityRate=1;s::GpuSmokeFireSolver solver(rig.device.p,rig.fence.p,p,{16*1024*1024,1,4096});std::string error;auto initial=s::initialState(p);require(solver.setInputs(in,error,&initial),error.c_str());tick(rig,solver,0,.01f);const auto bytes=solver.stats().allocationBytes;require(!solver.setInputs(in,error,&initial)&&solver.stats().allocationBytes==bytes,"Initial-state update silently reset a running solver");for(auto& c:in)c.densityRate=2;require(solver.setInputs(in,error)&&solver.stats().inputSnapshots==1,"Completed active snapshot blocked a one-slot input configuration");tick(rig,solver,1,.01f);const auto gpu=read(rig,solver);for(auto value:gpu.state.scalars)require(std::abs(value-.03f)<1e-6f,"One-slot source replacement reset or corrupted smoke history");rig.begin();const auto calls=solver.stats().dispatches;require(!solver.step(rig.commands.p,rig.ticket(),1,.01f,error)&&solver.stats().dispatches==calls&&!solver.stats().failed,"Duplicate simulation tick recorded work");rig.submit();cases.push_back({{"case","single-snapshot-reuse"},{"snapshotSlots",1},{"runningInitialResetRejected",true},{"duplicateTickRejectedBeforeCommands",true}});close(rig,solver);++groups;
}

}
int main(int argc,char** argv){try{std::string adapter;if(argc==3&&std::string(argv[1])=="--adapter")adapter=argv[2];else if(argc!=1)throw std::runtime_error("Usage: native_smoke_tests [--adapter substring]");Rig rig(adapter);require(rig.debug,"Actual smoke debug layer unavailable");std::cerr<<"begin equilibrium\n";equilibrium(rig);std::cerr<<"begin pressureAndBarrier\n";pressureAndBarrier(rig);std::cerr<<"begin movingSolid\n";movingSolid(rig);std::cerr<<"begin combustionAndCooling\n";combustionAndCooling(rig);std::cerr<<"begin boundsAndCfl\n";boundsAndCfl(rig);std::cerr<<"begin optionalChannelsAndBudget\n";optionalChannelsAndBudget(rig);std::cerr<<"begin realFenceInputs\n";realFenceInputs(rig);std::cerr<<"begin nonuniformTransport\n";nonuniformTransport(rig);std::cerr<<"begin singleSnapshotReuse\n";singleSnapshotReuse(rig);const auto errors=rig.debugErrors();require(errors==0,"Smoke D3D12 debug layer errors");std::cout<<nlohmann::json{{"schema","nativegpu.smoke-solver-evidence/1"},{"ok",true},{"groups",groups},{"checks",checks},{"comparisons",comparisons},{"adapter",rig.adapter},{"debugLayer",rig.debug},{"debugErrors",errors},{"cases",cases},{"runtimeReadback",false},{"rendererIntegrated",false},{"worldFieldIntegrated",false}}.dump()<<'\n';}catch(const std::exception& e){std::cerr<<"Smoke solver failed after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}}
